      searchUser: "https://www.acfun.cn/rest/pc-direct/search/user",
      searchArticle: "https://www.acfun.cn/rest/pc-direct/search/article",
      // ---- 弹幕（www.acfun.cn 同域，网页 Cookie 鉴权） ----
