  var RE_MOMENT_URL = /(?:https?:\/\/www\.acfun\.cn\/moment\/am|https?:\/\/m\.acfun\.cn\/communityCircle\/moment\/)(\d+)(?:\/?\?[^\s]*)?(?:#[^\s]*)?/ig;
  var RE_TAIL_PUNCT = /[\s.,;:!?)\]】」』。、！？；：]+$/;
  var RE_HEAD_PUNCT = /^[\s.,;:!?(\[【「『。、！？；：]+/;
