  var SITE_KEY = "searchCache";
  var LEGACY_KEY = "acsvSearchHist";
  var HIST_MAX = 8;
  var memArr = null;
  var merged = false;
  function ls() {
    try {
      if (typeof localStorage !== "undefined" && localStorage) return localStorage;
    } catch (e) {
    }
    return null;
  }
  function safeWord(s) {
    return String(s == null ? "" : s).replace(/[<>]/g, "").trim();
  }
  function readRaw() {
    var L = ls();
    if (!L) return memArr ? memArr.slice() : [];
    var j = null;
    try {
      j = JSON.parse(L.getItem(SITE_KEY));
    } catch (e) {
      j = null;
    }
    return Array.isArray(j) ? j : [];
  }
  function putArr(a) {
    var L = ls();
    if (!L) {
      memArr = a.slice();
      return;
    }
    try {
      L.setItem(SITE_KEY, JSON.stringify(a));
    } catch (e) {
      memArr = a.slice();
    }
  }
  function mergeLegacy(arr) {
    if (merged) return arr;
    merged = true;
    var old = "";
    try {
      if (typeof GM_getValue === "function") old = String(GM_getValue(LEGACY_KEY, "") || "");
    } catch (e) {
    }
    if (!old) return arr;
    var j = null;
    try {
      j = JSON.parse(old);
    } catch (e) {
      j = null;
    }
    if (!Array.isArray(j)) return arr;
    var next = arr.slice();
    j.forEach(function(w) {
      var k = safeWord(w);
      if (!k || next.indexOf(k) >= 0) return;
      next.push(k);
    });
    if (next.length > HIST_MAX) next.length = HIST_MAX;
    putArr(next);
    return next;
  }
  function histList() {
    var arr = readRaw().filter(function(x) {
      return typeof x === "string" && x;
    }).map(safeWord).filter(function(x) {
      return x;
    }).slice(0, HIST_MAX);
    return mergeLegacy(arr);
  }
  function histAdd(kw) {
    var k = safeWord(kw);
    if (!k) return;
    var a = histList();
    a = a.filter(function(x) {
      return x !== k;
    });
    a.unshift(k);
    if (a.length > HIST_MAX) a.length = HIST_MAX;
    putArr(a);
  }
  function histClear() {
    merged = true;
    memArr = [];
    var L = ls();
    if (!L) return;
    try {
      L.removeItem(SITE_KEY);
    } catch (e) {
    }
  }

